function validate([vals, edges, k]) {
  if (!Array.isArray(vals) || vals.length < 1 || vals.length > 100000) return 'vals needs 1 to 10^5 values.';
  const n = vals.length;
  if (vals.some(v => !Number.isInteger(v) || v < -10000 || v > 10000)) return 'Each value is between -10^4 and 10^4.';
  if (!Array.isArray(edges) || edges.length > Math.min((n * (n - 1)) / 2, 100000)) return 'Too many edges for this many nodes.';
  const seen = new Set();
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is [a, b].';
    const [a, b] = edge;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Edge ends are nodes 0 to n - 1.';
    if (a === b) return 'An edge joins two different nodes.';
    const key = Math.min(a, b) * 200000 + Math.max(a, b);
    if (seen.has(key)) return 'The same edge appears twice.';
    seen.add(key);
  }
  if (!Number.isInteger(k) || k < 0 || k > n - 1) return 'k is between 0 and n - 1.';
  return null;
}

