function maxStarSum(vals, edges, k) {
  const gains = vals.map(() => []);
  for (const [a, b] of edges) {
    if (vals[b] > 0) gains[a].push(vals[b]);
    if (vals[a] > 0) gains[b].push(vals[a]);
  }
  let best = -Infinity;
  for (let center = 0; center < vals.length; center++) {
    const options = gains[center];
    options.sort((x, y) => y - x);
    let sum = vals[center];
    const take = Math.min(k, options.length);
    for (let i = 0; i < take; i++) {
      sum += options[i];
    }
    best = Math.max(best, sum);
  }
  return best;
}

