function maxStarSum(vals, edges, k) {
  // Try every centre with every subset of its neighbours of size at most k.
  const n = vals.length;
  const neighbours = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { neighbours[a].push(b); neighbours[b].push(a); }
  let best = null;
  for (let c = 0; c < n; c++) {
    const list = neighbours[c];
    for (let mask = 0; mask < (1 << list.length); mask++) {
      let bits = 0, total = vals[c];
      for (let i = 0; i < list.length; i++) if (mask & (1 << i)) { bits++; total += vals[list[i]]; }
      if (bits <= k && (best === null || total > best)) best = total;
    }
  }
  return best;
}

