function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(1000, 2000) : int(1, 8);
  const span = large || rand() < 0.2 ? 10000 : 10;
  const shift = rand() < 0.2 ? -span : rand() < 0.2 ? span : 0;
  const vals = Array.from({ length: n }, () => Math.max(-10000, Math.min(10000, int(-span, span) + Math.floor(shift / 2))));
  const maxPairs = (n * (n - 1)) / 2;
  const edgeCount = large ? Math.min(maxPairs, int(1500, 2000)) : int(0, Math.min(maxPairs, 12));
  const hubs = large ? Array.from({ length: int(1, 5) }, () => int(0, n - 1)) : [];
  const used = new Set();
  const edges = [];
  while (edges.length < edgeCount) {
    const a = hubs.length && rand() < 0.5 ? hubs[int(0, hubs.length - 1)] : int(0, n - 1);
    const b = int(0, n - 1);
    if (a === b) continue;
    const key = Math.min(a, b) * 200000 + Math.max(a, b);
    if (used.has(key)) continue;
    used.add(key);
    edges.push([a, b]);
  }
  const roll = rand();
  const k = n === 1 ? 0 : roll < 0.2 ? 0 : roll < 0.4 ? n - 1 : int(0, large ? Math.min(n - 1, 300) : n - 1);
  return [vals, edges, k];
}
